package org.updraft.betterstatus.monitor;
import org.updraft.betterstatus.api.*; import org.updraft.betterstatus.model.*; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicBoolean;
public final class MonitorEngine implements ServerStatusApi,AutoCloseable {
 private final Map<String,PingProvider> providers=new ConcurrentHashMap<>(); private final ConcurrentMap<String,ServerSnapshot> snapshots=new ConcurrentHashMap<>(); private final ConcurrentMap<String,Integer> failures=new ConcurrentHashMap<>(),recoveries=new ConcurrentHashMap<>(); private final CopyOnWriteArrayList<StatusListener> listeners=new CopyOnWriteArrayList<>(); private final ScheduledExecutorService scheduler=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"BetterStatus-Scheduler");t.setDaemon(true);return t;}); private final ExecutorService workers=Executors.newFixedThreadPool(8,r->{Thread t=new Thread(r,"BetterStatus-Ping");t.setDaemon(true);return t;}); private final MonitorConfig config; private final AtomicBoolean running=new AtomicBoolean();
 public MonitorEngine(Map<String,PingProvider> providers,MonitorConfig config){providers.forEach((n,p)->{String k=key(n);this.providers.put(k,p);snapshots.put(k,unknown(k));});this.config=config;}
 private static String key(String n){return n.toLowerCase(Locale.ROOT);} private static ServerSnapshot unknown(String n){long t=System.currentTimeMillis();return new ServerSnapshot(n,ServerState.UNKNOWN,0,0,-1,"","",false,0,t,t,0,"Waiting for first check");}
 public void start(){if(running.compareAndSet(false,true)){refreshAll();scheduler.scheduleWithFixedDelay(this::refreshAll,config.intervalMillis(),config.intervalMillis(),TimeUnit.MILLISECONDS);}}
 public void refreshAll(){providers.keySet().forEach(this::checkServer);}
 public CompletableFuture<Optional<ServerSnapshot>> checkServer(String name){String k=key(name);PingProvider p=providers.get(k);if(p==null)return CompletableFuture.completedFuture(Optional.empty());return CompletableFuture.supplyAsync(p::ping,workers).thenCompose(x->x).orTimeout(config.timeoutMillis(),TimeUnit.MILLISECONDS).exceptionally(e->PingResult.failure(e.getClass().getSimpleName())).thenApply(result->Optional.of(apply(k,result)));}
 private ServerSnapshot apply(String n,PingResult p){long now=System.currentTimeMillis();ServerSnapshot old=snapshots.getOrDefault(n,unknown(n));ServerState state;long success=old.lastSuccessMillis(),up=old.uptimeSinceMillis();if(p.reachable()){failures.put(n,0);int r=recoveries.merge(n,1,Integer::sum);success=now;state=(old.state()==ServerState.OFFLINE||old.state()==ServerState.UNREACHABLE||old.state()==ServerState.RESTARTING)&&r<config.recoveryThreshold()?ServerState.STARTING:(p.pingMillis()>=config.warningPingMillis()?ServerState.DEGRADED:ServerState.ONLINE);if(state==ServerState.ONLINE&&(old.state()!=ServerState.ONLINE||up==0))up=now;}else{recoveries.put(n,0);state=failures.merge(n,1,Integer::sum)>=config.failureThreshold()?ServerState.OFFLINE:ServerState.UNREACHABLE;up=0;}long changed=state==old.state()?old.stateChangedMillis():now;ServerSnapshot current=new ServerSnapshot(n,state,p.players(),p.maxPlayers(),p.pingMillis(),p.motd(),p.version(),old.maintenance(),success,now,changed,up,p.failureReason());snapshots.put(n,current);if(state!=old.state())for(StatusListener l:listeners)try{l.onStatusChange(old,current);}catch(RuntimeException ignored){}return current;}
 public void setMaintenance(String name,boolean enabled){String k=key(name);snapshots.computeIfPresent(k,(x,s)->new ServerSnapshot(s.name(),enabled?ServerState.MAINTENANCE:(s.state()==ServerState.MAINTENANCE?ServerState.ONLINE:s.state()),s.players(),s.maxPlayers(),s.pingMillis(),s.motd(),s.version(),enabled,s.lastSuccessMillis(),s.lastCheckMillis(),System.currentTimeMillis(),s.uptimeSinceMillis(),enabled?"Maintenance mode":""));}
 public Optional<ServerSnapshot> getServer(String n){return Optional.ofNullable(snapshots.get(key(n)));} public Collection<ServerSnapshot> getServers(){return List.copyOf(snapshots.values());} public void addListener(StatusListener l){listeners.add(Objects.requireNonNull(l));} public void removeListener(StatusListener l){listeners.remove(l);} public void close(){running.set(false);scheduler.shutdownNow();workers.shutdownNow();}
}